// import React, { useState, useEffect } from 'react';
import './Home.css';
import profileImage from '../assets/picture.jpg';

const Home = () => {
  const fullName = "H i, I'm Shashank Shankaregowda";
  const [displayedName, setDisplayedName] = useState('');
  const [showSubtitle, setShowSubtitle] = useState(false);

  useEffect(() => {
    let index = 0;
    const interval = setInterval(() => {
      setDisplayedName((prev) => prev + fullName.charAt(index));
      index++;
      if (index >= fullName.length) {
        clearInterval(interval);
        setTimeout(() => setShowSubtitle(true), 100);
      }
    }, 30);

    return () => clearInterval(interval);
  }, []);

  return (
    <section id="home" className="home">
      {/* Video Background */}
      <video
        className="video-background"
        autoPlay
        muted
        loop
        playsInline
      >
        <source src="/assets/bg-video.mp4" type="video/mp4" />
        Your browser does not support the video tag.
      </video>

      {/* Overlay for color & content */}
      <div className="overlay">
        <div className="home-content">
          <div className="home-text">
            <h1 className="fade-in-effect">{displayedName}</h1>
            {showSubtitle && (
              <p className="location fade-in-subtitle">
                Innovating Software Engineering with Scalable Solutions and AI
              </p>
            )}
            <div className="resume-download">
              <a href="/Shashank.pdf" download="Shashank_Shankaregowda_Resume.pdf">
                <button className="download-button">Download Resume</button>
              </a>
            </div>
          </div>
          <img src={profileImage} alt="Shashank Shankaregowda" className="profile-image" />
        </div>
      </div>
    </section>
  );
};

export default Home;
